from pathlib import Path
p=Path('index.html')
s=p.read_text(encoding='utf-8')
css='''<style id="anvora-production-ux">body.poc-connectors-active nav,body.poc-connectors-active .nav{transform:none!important;visibility:visible!important;opacity:1!important}#anvoraEvidenceSummary{margin:16px 0;padding:20px;border:1px solid #dce7e2;border-radius:16px;background:#fff;box-shadow:0 8px 28px rgba(18,52,42,.06)}#anvoraEvidenceSummary .ae-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:14px}#anvoraEvidenceSummary .ae-item{padding:13px;border:1px solid #e5ece8;border-radius:12px;background:#f8fbf9}#anvoraEvidenceSummary .ae-label{font-size:11px;text-transform:uppercase;letter-spacing:.07em;color:#6d7d76;font-weight:800}#anvoraEvidenceSummary .ae-value{font-size:17px;font-weight:800;margin-top:4px}#anvoraEvidenceSummary .ae-note{margin-top:14px;padding:11px 12px;border-left:4px solid #176b52;background:#eef7f3;border-radius:7px}#anvoraEvidenceSummary .ae-visual{margin-top:14px;padding:14px;border:1px solid #e5ece8;border-radius:12px;background:#fbfcfb}#anvoraEvidenceSummary canvas{width:100%;height:180px;display:block}.anvora-tech-toggle{position:fixed;right:16px;bottom:16px;z-index:9999;border:1px solid #cfdcd7;background:#fff;color:#17302a;border-radius:999px;padding:9px 13px;font-weight:700;box-shadow:0 5px 18px rgba(18,52,42,.12);cursor:pointer}body.anvora-simple-mode pre,body.anvora-simple-mode .debug,body.anvora-simple-mode .technical-detail,body.anvora-simple-mode .raw-output{display:none!important}@media(max-width:850px){#anvoraEvidenceSummary .ae-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:560px){#anvoraEvidenceSummary .ae-grid{grid-template-columns:1fr}}</style>'''
js='''<script id="anvora-production-ux-script">(function(){const $=id=>document.getElementById(id);const esc0=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));function navFix(){document.body.classList.remove('poc-connectors-active');const n=document.querySelector('nav');if(n){n.style.transform='none';n.style.visibility='visible';n.style.opacity='1'}}function selectedItem(){const o=window.ANVORA_EO_OBSERVATION;if(o&&o.acquisitionId)return o;const live=window.ANVORA_LIVE_ACQUISITIONS;const items=live?.response?.items||[];const rs=[...document.querySelectorAll('input[name="eoAcqSelect"]')];const i=Math.max(0,rs.findIndex(r=>r.checked));return items[i]||items[0]||null}function findStats(){const r=window.ANVORA_S1_RESULT,d=r?.data,ints=Array.isArray(d?.data)?d.data:[],out=[];ints.forEach(it=>{const b=it?.outputs?.backscatter?.bands||{};Object.keys(b).forEach(k=>{const st=b[k]?.stats;if(st)out.push({band:k,mean:Number(st.mean),median:Number(st.median),sd:Number(st.stDev),n:Number(st.sampleCount)})})});return out}function visualise(stats){const c=document.querySelector('#anvoraEvidenceSummary canvas');if(!c||!stats.length)return;const w=c.clientWidth||700,h=180,dpr=devicePixelRatio||1;c.width=w*dpr;c.height=h*dpr;const x=c.getContext('2d');x.scale(dpr,dpr);const v=stats.map(a=>a.mean).filter(Number.isFinite);if(!v.length)return;const mi=Math.min(...v),ma=Math.max(...v),sp=Math.max(.1,ma-mi);x.strokeStyle='#dce7e2';x.beginPath();x.moveTo(42,145);x.lineTo(w-20,145);x.stroke();const bw=Math.min(120,(w-90)/Math.max(1,stats.length)-18);stats.forEach((a,i)=>{const bh=25+(a.mean-mi)/sp*90,xx=55+i*(bw+18),yy=145-bh;x.fillStyle='#176b52';x.fillRect(xx,yy,bw,bh);x.fillStyle='#17302a';x.font='12px system-ui';x.textAlign='center';x.fillText(a.band,xx+bw/2,162);x.fillText(a.mean.toFixed(2)+' dB',xx+bw/2,yy-7)});x.textAlign='left';x.fillStyle='#61736d';x.font='11px system-ui';x.fillText('Measured Sentinel-1 backscatter mean — evidence visualization',42,18)}function evidenceSummary(){const page=$('remoteEvidence');if(!page)return;let box=$('anvoraEvidenceSummary');if(!box){box=document.createElement('div');box.id='anvoraEvidenceSummary';const main=page.querySelector('.re-main')||page;main.insertBefore(box,main.firstChild)}const o=window.ANVORA_EO_OBSERVATION||{},it=selectedItem()||{},stats=findStats(),measured=!!window.ANVORA_S1_RESULT&&!window.ANVORA_S1_RESULT.simulated,bands=stats.map(a=>a.band+': '+a.mean.toFixed(2)+' dB').join(' · '),dt=o.acquisitionDateTime||it.datetime||'',url=o.stacItemUrl||it.self||'';box.innerHTML='<div class="kicker">FIELD OBSERVATION</div><h2>'+(measured?'Satellite evidence processed':'Observation record created')+'</h2><p class="muted">'+(measured?'Measured Sentinel-1 evidence is available for this acquisition.':'The acquisition is confirmed, but image processing has not yet produced measured field metrics.')+'</p><div class="ae-grid"><div class="ae-item"><div class="ae-label">Status</div><div class="ae-value">'+(measured?'Measured':'Metadata only')+'</div></div><div class="ae-item"><div class="ae-label">Observation</div><div class="ae-value">'+esc0(o.observationId||'Not created')+'</div></div><div class="ae-item"><div class="ae-label">Date</div><div class="ae-value">'+esc0(dt?new Date(dt).toLocaleDateString():'—')+'</div></div><div class="ae-item"><div class="ae-label">Signal</div><div class="ae-value">'+esc0(bands||'Not yet measured')+'</div></div></div><div class="ae-note"><b>Plain-language interpretation:</b> '+(measured?'A measurable radar signal has been returned for the selected acquisition. A practice such as drainage, irrigation or fertilizer application is <b>not inferred automatically</b> from this single observation.':'The catalogue confirms that a Sentinel-1 acquisition exists for the selected field context. No practice conclusion is established yet.')+'</div><div class="ae-visual"><b>Visual evidence</b><p class="muted" style="margin:4px 0 8px">'+(measured?'Measured SAR statistics visualized from the returned observation. This is an evidence visualization, not a photograph and not a fabricated satellite image.':'A visual satellite product is not shown until imagery/derived metrics are actually returned.')+'</p><canvas></canvas>'+(url?'<div style="margin-top:8px"><a href="'+esc0(url)+'" target="_blank" rel="noopener">Open source STAC record</a></div>':'')+'</div>';visualise(stats)}function addProcessButton(){const page=$('remoteEvidence');if(!page)return;const head=page.querySelector('.re-head');if(!head||head.querySelector('#anvoraProcessS1'))return;const b=document.createElement('button');b.id='anvoraProcessS1';b.className='primary';b.style.marginTop='12px';b.textContent='Process selected Sentinel-1 evidence';b.onclick=async function(){try{if(typeof loadSelectedAcqIntoS1==='function')loadSelectedAcqIntoS1();if(typeof runS1Backend==='function')await runS1Backend();else throw new Error('Sentinel-1 backend runner is unavailable in this build.');evidenceSummary()}catch(e){alert('Sentinel-1 processing could not be completed: '+(e?.message||e))}};head.appendChild(b)}function tech(){if(document.querySelector('.anvora-tech-toggle'))return;const b=document.createElement('button');b.className='anvora-tech-toggle';b.textContent='Technical details';b.onclick=()=>{document.body.classList.toggle('anvora-simple-mode');b.textContent=document.body.classList.contains('anvora-simple-mode')?'Show technical details':'Technical details'};document.body.classList.add('anvora-simple-mode');document.body.appendChild(b)}const sp=window.showPage;if(typeof sp==='function')window.showPage=function(id){navFix();const r=sp.apply(this,arguments);setTimeout(()=>{navFix();if(id==='remoteEvidence'){addProcessButton();evidenceSummary()}},30);return r};const rr=window.renderRemoteEvidence;if(typeof rr==='function')window.renderRemoteEvidence=function(){const r=rr.apply(this,arguments);setTimeout(()=>{addProcessButton();evidenceSummary()},0);return r};const rb=window.runS1Backend;if(typeof rb==='function')window.runS1Backend=async function(){const r=await rb.apply(this,arguments);setTimeout(evidenceSummary,50);return r};document.addEventListener('click',()=>setTimeout(navFix,0));window.addEventListener('load',()=>{navFix();tech();addProcessButton();evidenceSummary()});setTimeout(()=>{navFix();tech();addProcessButton();evidenceSummary()},250)})();</script>'''
backend='''<script id="anvora-v456-s1-backend-runner">\nasync function runS1Backend(){\n  const req=window.ANVORA_S1_REQUEST||buildS1StatsRequest();\n  const endpoint=(document.getElementById('s1Endpoint')||{}).value||'https://anvora-eo-connector.raja-vadlamani.workers.dev/api/sentinel1';\n  const o=window.ANVORA_EO_OBSERVATION||selectedAcqForS1();\n  const status=document.getElementById('s1Status');\n  if(status) status.innerHTML='<div class="control-row"><div><b>Running Sentinel-1 processing</b><small>Sending the selected acquisition and Statistical API contract to the protected ANVORA backend.</small></div><span class="pill">Running…</span></div>';\n  try{\n    const payload={request:req.body,observation:o,source:'ANVORA',algorithmVersion:'ANVORA-EO-S1-0.1'};\n    const r=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(payload)});\n    const text=await r.text();\n    let data; try{data=text?JSON.parse(text):null}catch(e){throw new Error('Backend returned non-JSON response (HTTP '+r.status+').');}\n    if(!r.ok || data?.status==='ERROR' || data?.error) throw new Error(data?.error||('Backend request failed with HTTP '+r.status));\n    renderS1Result(data,false);\n    window.ANVORA_S1_RESULT={simulated:false,data};\n    if(window.ANVORA_EO_OBSERVATION){window.ANVORA_EO_OBSERVATION.processingStatus='PROCESSED';window.ANVORA_EO_OBSERVATION.algorithmVersion='ANVORA-EO-S1-0.1';window.ANVORA_EO_OBSERVATION.derivedMetrics=data?.data||data?.derivedMetrics||[];window.ANVORA_EO_OBSERVATION.assuranceNote='Sentinel-1 processing returned measured SAR statistics. These measurements do not by themselves prove a farmer practice.';const pre=document.getElementById('eoJson');if(pre)pre.textContent=JSON.stringify(window.ANVORA_EO_OBSERVATION,null,2);}\n    if(status) status.innerHTML='<div class="control-row"><div><b>Sentinel-1 processing completed</b><small>Measured SAR statistics returned from the ANVORA backend.</small></div><span class="pill">Measured</span></div>';\n    return data;\n  }catch(err){\n    if(status) status.innerHTML='<div class="control-row"><div><b>Sentinel-1 processing failed</b><small>'+esc(err?.message||String(err))+'</small></div><span class="pill">Review</span></div>';\n    throw err;\n  }\n}\n</script>'''
if 'anvora-production-ux' not in s:s=s.replace('</head>',css+'</head>',1)
if 'anvora-production-ux-script' not in s:s=s.replace('</body>',js+'</body>',1)
if 'anvora-v456-s1-backend-runner' not in s:s=s.replace('</body>',backend+'</body>',1)
old="items:features.map(f=>({id:f.id,datetime:f.properties?.datetime,collection:f.collection,links:f.links,bbox:f.bbox||null,self:(f.links||[]).find(x=>x.rel==='self')?.href||null}))"
new="items:features.map(f=>({id:f.id,datetime:f.properties?.datetime,collection:f.collection,links:f.links,bbox:f.bbox||null,self:(f.links||[]).find(x=>x.rel==='self')?.href||null,assets:f.assets||{},geometry:f.geometry||null}))"
if old in s:s=s.replace(old,new,1)
p.write_text(s,encoding='utf-8')
